{{-- ══════ БЛОКИРУЮЩАЯ ПРОВЕРКА ТАЙМЕРА — выполняется синхронно, сразу ══════
     ВАЖНО: base.blade.php — общий layout, и Livewire wire:navigate перерисовывает
     его на каждом переходе, включая этот partial. Значит #pbPreloader — это
     каждый раз СВЕЖИЙ DOM-узел с чистого сервера. Если просто проверять флаг
     "уже запускались" и выходить — на второй странице узел откроется в дефолтном
     видимом состоянии и закроет весь сайт. Поэтому: после первого прогона в
     этой вкладке — на ВСЕХ следующих прогонах прелоадер прячем сразу и безусловно. --}}
<script>
(function() {
    var pre = document.getElementById('pbPreloader');
    if (!pre) return;

    if (window.__pbPreloaderDone) {
        // уже показывали (или решили не показывать) в этой вкладке — больше никогда
        pre.style.display = 'none';
        return;
    }
    window.__pbPreloaderDone = true;

    var KEY = 'pandbox_preloader_last_shown';
    var COOLDOWN = 3 * 60 * 1000; // 3 minutes

    var now = Date.now();
    var last = 0;
    try { last = parseInt(localStorage.getItem(KEY) || '0', 10) || 0; } catch (e) {}

    try { localStorage.setItem(KEY, String(now)); } catch (e) {}

    pre.setAttribute('data-play', '1');
    document.documentElement.style.overflow = 'hidden';
})();
</script>

