<script>
(function() {
    if (window.__pbPreloaderAnimBooted) return;
    window.__pbPreloaderAnimBooted = true;

    var pre = document.getElementById('pbPreloader');
    if (!pre || pre.getAttribute('data-play') !== '1') return;

    function finish() {
        pre.style.display = 'none';
        document.documentElement.style.overflow = '';
    }

    if (typeof gsap === 'undefined') {
        finish();
        return;
    }

    var pieces = pre.querySelectorAll('.pb-piece');
    var word = document.getElementById('pbPreWordText');
    var bullets = pre.querySelectorAll('.pb-bullet');

    var tl = gsap.timeline({ onComplete: finish });

    /* 1. Кусочки панды разлетаются по экрану и собираются на место */
    tl.set(pieces, {
        x: function() { return gsap.utils.random(-700, 700); },
        y: function() { return gsap.utils.random(-500, 500); },
        rotation: function() { return gsap.utils.random(-220, 220); },
        scale: 0.15,
        opacity: 0
    });
    tl.to(pieces, {
        x: 0, y: 0, rotation: 0, scale: 1, opacity: 1,
        duration: 0.9,
        ease: 'back.out(1.5)',
        stagger: { each: 0.005, from: 'random' }
    }, 0.15);
    /* ^ при 77 деталях и stagger.each=0.005 группа расползается ещё на ~0.38с,
         значит визуально кусочки долетают и садятся примерно к отметке ~1.43с */

    /* 2. Пробоины от пуль — появляются ПО ОДНОЙ, пока панда ещё собирается,
          будто по ней стреляют в процессе сборки */
    var bulletStart = 0.35;
    var bulletGap = 0.2;
    bullets.forEach(function(bullet, i) {
        tl.to(bullet, {
            scale: 1,
            opacity: 1,
            duration: 0.22,
            ease: 'back.out(3.5)'
        }, bulletStart + i * bulletGap);

        // микро-встряска логотипа в момент каждого попадания
        tl.to('#pbPreLogo', {
            x: (i % 2 === 0) ? 4 : -4,
            duration: 0.04,
            yoyo: true,
            repeat: 3,
            ease: 'power1.inOut'
        }, bulletStart + i * bulletGap);
    });
    tl.set('#pbPreLogo', { x: 0 }, bulletStart + bullets.length * bulletGap + 0.1);

    /* 3. Вордмарк PANDBOX.KZ выезжает, когда панда собрана и все пробоины на месте */
    var wordmarkStart = bulletStart + bullets.length * bulletGap + 0.15;
    tl.fromTo(word,
        { opacity: 0, y: 26, scale: 0.85 },
        { opacity: 1, y: 0, scale: 1, duration: 0.5, ease: 'back.out(1.7)' },
        wordmarkStart
    );

    /* небольшая пауза чтобы налюбоваться */
    tl.to({}, { duration: 0.4 });

    /* 4. Экран уезжает вниз, открывая сайт */
    tl.to(pre, {
        yPercent: 100,
        duration: 0.85,
        ease: 'power4.inOut'
    });

    window.__pbPreloaderReplay = function() {
        if (!document.documentElement.contains(pre) || tl.isActive()) return;

        try { localStorage.setItem('pandbox_preloader_last_shown', String(Date.now())); } catch (e) {}

        pre.style.display = 'block';
        pre.setAttribute('data-play', '1');
        document.documentElement.style.overflow = 'hidden';
        gsap.set(pre, { yPercent: 0 });
        tl.restart(true);
    };

    function armPreloaderForHome() {
        if (window.__pbPreloaderRepeatTimer) {
            window.clearTimeout(window.__pbPreloaderRepeatTimer);
        }
        window.__pbPreloaderReadyForHome = false;
        window.__pbPreloaderRepeatTimer = window.setTimeout(function() {
            window.__pbPreloaderReadyForHome = true;
            window.__pbPreloaderRepeatTimer = null;
        }, 3 * 60 * 1000);
    }

    if (!window.__pbPreloaderHomeNavigationBooted) {
        window.__pbPreloaderHomeNavigationBooted = true;
        document.addEventListener('livewire:navigated', function() {
            var isHome = window.location.pathname.replace(/\/+$/, '') === '';
            if (!isHome || !window.__pbPreloaderReadyForHome || document.hidden) return;

            window.__pbPreloaderReadyForHome = false;
            if (typeof window.__pbPreloaderReplay === 'function') {
                window.__pbPreloaderReplay();
            }
            armPreloaderForHome();
        });
    }

    armPreloaderForHome();
})();
</script>
